local function state()
    local ps = reaper.GetPlayState()
    local playing = ps & 1 ~= 0
    return {
        playing = playing, paused = ps & 2 ~= 0, recording = ps & 4 ~= 0,
        position = (playing or ps & 2 ~= 0) and reaper.GetPlayPosition() or reaper.GetCursorPosition(),
