    if p.selected ~= nil then reaper.SetMediaItemInfo_Value(it, "B_UISEL", p.selected and 1 or 0) end
    if p.color ~= nil then reaper.SetMediaItemInfo_Value(it, "I_CUSTOMCOLOR", color_to_native(p.color)) end
